const locations = $json;
if (locations.length === 0) return [];

const userId = locations[0].user_id;

// Get user settings for fog radius
const settings = await $getAll('user_settings', {
  where: { user_id: userId }
});

const radius = settings[0]?.fog_reveal_radius || 50;

// Calculate explored tiles for each zoom level
const zoomLevels = [0, 1, 2, 3, 4];
const updates = [];

for (const zoom of zoomLevels) {
  const tileSize = 256 * Math.pow(2, 18 - zoom); // Approximate meters per tile
  const radiusInTiles = Math.ceil(radius / (tileSize / 256));

  for (const loc of locations) {
    const tileX = Math.floor((loc.longitude + 180) / 360 * Math.pow(2, zoom));
    const tileY = Math.floor(
      (1 - Math.log(Math.tan(loc.latitude * Math.PI / 180) + 1 / Math.cos(loc.latitude * Math.PI / 180)) / Math.PI) / 2 * Math.pow(2, zoom)
    );

    // Mark surrounding tiles as explored
    for (let dx = -radiusInTiles; dx <= radiusInTiles; dx++) {
      for (let dy = -radiusInTiles; dy <= radiusInTiles; dy++) {
        const key = `${zoom}/${tileX + dx}/${tileY + dy}`;
        updates.push({
          user_id: userId,
          tile_key: key,
          zoom_level: zoom,
          center_lat: loc.latitude,
          center_lng: loc.longitude,
          accuracy: loc.accuracy
        });
      }
    }
  }
}

return updates;

// Update user stats
const userId = $json[0].user_id;

// Count explored tiles
const exploredCount = await $executeQuery(
  `SELECT COUNT(*) as count FROM explored_areas WHERE user_id = '${userId}'`
);

// Update stats
await $executeQuery(
  `UPDATE user_stats SET 
    explored_tiles = ${exploredCount[0].count},
    last_explored_at = NOW(),
    updated_at = NOW()
   WHERE user_id = '${userId}'`
);

return { success: true, user_id: userId, explored_tiles: exploredCount[0].count };
